// notie
import * as notie from "notie";
import "notie/dist/notie.css";
// open-sans
import "@fontsource/open-sans";
// basthon
import { GUIBase } from "@basthon/gui-base";
export default class GUI extends GUIBase {
    constructor(options) {
        super({ ...options, uiName: "console" });
        this._urlKey = "script";
        this._contentFilename = "script";
        /* when kernel is available, set contentFilename extension */
        this.kernelLoader.kernelAvailable().then((kernel) => {
            const exts = kernel.moduleExts();
            if (exts.length)
                this._contentFilename += "." + exts[0];
        });
    }
    /**
     * Set editor.
     */
    setEditor(editor) {
        this._editor = editor;
    }
    /**
     * Set terminal.
     */
    setTerminal(term) {
        this._term = term;
    }
    /**
     * Set graphics.
     */
    setGraphics(graphics) {
        graphics.setDynamicIFrameHandler(this.handleDynamicIFrame.bind(this));
        this._graphics = graphics;
    }
    /**
     * get editor.
     */
    get editor() {
        return this._editor;
    }
    /**
     * get terminal.
     */
    terminal() {
        return this._term;
    }
    /**
     * get graphics.
     */
    get graphics() {
        return this._graphics;
    }
    /**
     * Get editor's content.
     */
    content() {
        return this._editor?.getContent();
    }
    /**
     * Set editor's content.
     */
    setContent(content) {
        this._editor?.setContent(content);
    }
    /**
     * Notify the user with an error.
     */
    error(title, message) {
        notie.alert({
            type: "error",
            text: message,
            stay: false,
            time: 3,
            position: "top",
        });
    }
    /**
     * Notify the user.
     */
    info(title, message) {
        notie.alert({
            type: "success",
            text: message,
            stay: false,
            time: 3,
            position: "top",
        });
    }
    /**
     * Ask the user to confirm or cancel.
     */
    confirm(title, message, text, callback, textCancel, callbackCancel) {
        notie.confirm({
            text: message,
            submitText: text,
            cancelText: textCancel,
            position: "top",
            submitCallback: callback,
            cancelCallback: callbackCancel,
        });
    }
    /**
     * Ask the user to select a choice.
     */
    select(title, message, choices, textCancel, callbackCancel) {
        let count = 0;
        notie.select({
            text: message,
            cancelText: textCancel,
            position: "top",
            choices: choices.map((c) => ({
                text: c.text,
                type: count++ % 2 ? "error" : "success",
                handler: c.handler || (() => { }),
            })),
            cancelCallback: callbackCancel || (() => { }),
        });
    }
    /**
     * Rolling back to previous version
     */
    async rollback() {
        const content = await this.selectCheckpoint();
        if (content != null)
            this.setContent(content);
    }
    async setupUI(options) {
        await super.setupUI(options);
        /* binding ctrl+s */
        window.addEventListener("keydown", (event) => {
            if ((event.ctrlKey || event.metaKey) &&
                String.fromCharCode(event.which).toLowerCase() === "s") {
                event.preventDefault();
                this.download();
            }
        });
        /* backup before closing */
        window.onbeforeunload = () => {
            this.backup().catch(this.notifyError.bind(this));
        };
    }
    /**
     * Run the editor script in the terminal.
     */
    async runScript() {
        await this.loaded();
        const src = this.content();
        this._term?.launch(src, false);
        this._term?.focus();
    }
    /**
     * RAZ function.
     */
    restart() {
        this.kernelRestart();
        this._term?.clear();
        this._graphics?.clean();
    }
    /**
     * Open *.py file by asking user what to do:
     * load in editor or put on (emulated) local filesystem.
     */
    async openModuleFile(file) {
        this.confirm("", `Que faire de ${file.name} ?`, "Charger dans l'éditeur", () => {
            this.open(file);
        }, "Installer le module", () => {
            this.putFSRessource(file);
        });
    }
    /**
     * Opening file: If it has kernel extension, loading it in the editor
     * or put on (emulated) local filesystem (user is asked to),
     * otherwise, loading it in the local filesystem.
     */
    async openFile() {
        await this.kernelLoader.kernelAvailable();
        const callback = this.openModuleFile.bind(this);
        const callbacks = {};
        this.kernelSafe?.moduleExts().forEach((ext) => {
            callbacks[ext] = callback;
        });
        return await this._openFile(callbacks);
    }
}
