import { useEffect } from "react";
/* we use immer to fake mutable state */
import { useImmerReducer } from "use-immer";
import { Storage } from "@basthon/checkpoints";
/* this initial state */
const initialState = {
    ready: false,
    language: "python3",
    theme: "dark",
    viewMode: "default",
    rightPanel: "terminal",
    graphicsDirty: false,
    editorContent: "",
};
/* copy throught JSON, should be sufficient for what we do */
function copy(obj) {
    return JSON.parse(JSON.stringify(obj));
}
/* states to store */
const storedStates = ["theme", "viewMode", "rightPanel", "editorContent"];
/* get state from storage */
const stateFromStorage = async (language) => {
    const storage = new Storage(`console.${language}.states`);
    await storage.ready();
    const state = { ...initialState, language };
    for (let key of storedStates) {
        const storageValue = await storage.get(key);
        if (storageValue != null)
            state[key] = storageValue;
    }
    return state;
};
/* save state to storage */
const stateToStorage = async (state) => {
    const storage = new Storage(`console.${state.language}.states`);
    await storage.ready();
    for (let key of storedStates)
        await storage.set(key, state[key]);
};
/* where our global logic takes place */
const reducer = (state, action) => {
    const { type, payload } = action;
    switch (type) {
        case "init": {
            if (payload != null)
                state = copy(payload);
            state.ready = true;
            return state;
        }
        case "set-theme":
            state.theme = payload;
            break;
        case "switch-theme":
            state.theme = state.theme === "light" ? "dark" : "light";
            break;
        case "switch-view":
            state.viewMode = state.viewMode === "default" ? "reversed" : "default";
            break;
        case "set-view-mode":
            state.viewMode = payload;
            break;
        case "set-right-panel":
            state.rightPanel = payload;
            if (state.rightPanel === "graphics")
                state.graphicsDirty = false;
            break;
        case "graphics-dirty":
            if (state.rightPanel !== "graphics")
                state.graphicsDirty = true;
            break;
        case "set-editor-content":
            state.editorContent = payload;
            break;
        default:
            throw Error(`Internal error: unrecognized action type: '${type}'!`);
    }
    stateToStorage(copy(state));
};
/* stateManager exposed as API */
const stateManager = {
    useReducer: (language, initFromStorage) => {
        const [state, dispatch] = useImmerReducer(reducer, {
            ...initialState,
            language,
        });
        // dispatch init from storage
        useEffect(() => {
            (async () => {
                let payload = undefined;
                if (initFromStorage)
                    payload = await stateFromStorage(language);
                dispatch({ type: "init", payload });
            })();
        }, []);
        return [state, dispatch];
    },
    ready: (state) => state.ready,
    language: (state) => state.language,
    theme: (state) => state.theme,
    viewMode: (state) => state.viewMode,
    rightPanel: (state) => state.rightPanel,
    graphicsDirty: (state) => state.graphicsDirty,
    editorContent: (state) => state.editorContent,
};
export default stateManager;
