import $ from "jquery";
import "jquery.terminal";
import "jquery.terminal/css/jquery.terminal.css";
/**
 * Wrapper class arround JQTerminal.
 */
export default class Terminal {
    constructor(element, kernel) {
        // A buffer to handle multiline terminal input.
        this._buffer = [];
        // tell wether we are waiting for user input during
        // program execution (Python's input())
        this._inputMode = false;
        // array of destroy callbacks
        this._destroyCb = [];
        this._elem = element;
        this._kernel = kernel;
        // just to be safe
        this.resetBuffer();
        this._term = $(element).terminal(this._interpreter.bind(this), {
            greetings: this.banner(),
            prompt: kernel.ps1(),
            completionEscape: false,
            completion: async (command, callback) => {
                await kernel.ready();
                return (await kernel.complete(command))?.[0] ?? [];
            },
        });
        // this prevents JQuery Terminal to redraw terminal and remove
        // script wrapping feature
        // @ts-ignore
        // term.resize = () => {};
        /* Event connections */
        const events = {
            "eval.finished": (data) => {
                if (data.interactive && "result" in data) {
                    this.echo(data.result["text/plain"] + "\n");
                }
                this._term.set_prompt(this._kernel.ps1());
                this.wakeup();
            },
            "eval.output": (data) => {
                switch (data.stream) {
                    case "stdout":
                        this.echo(data.content);
                        break;
                    case "stderr":
                        this.error(data.content);
                        break;
                }
            },
            "eval.error": (data) => {
                this._term.set_prompt(this._kernel.ps1());
                this.wakeup();
            },
            "eval.input": (data) => {
                this._inputMode = true;
                const prompt = data?.content?.prompt;
                if (prompt != null)
                    this.echo(prompt);
                this._inputResolve = data.resolve;
                this.wakeup();
                this.focus();
            },
        };
        for (const event in events) {
            const callback = events[event];
            this._kernel.addEventListener(event, callback);
            // remember to remove listeners on destroy
            this._destroyCb.push(() => this._kernel.removeEventListener(event, callback));
        }
    }
    /**
     * Mimic CPython's REPL banner.
     */
    banner() {
        let banner = this._kernel.banner();
        banner = banner.replace("on WebAssembly/Emscripten", "");
        return banner;
    }
    /**
     * Reset the multiline input buffer.
     */
    resetBuffer() {
        this._buffer = [];
    }
    async _interpreter(command) {
        await this._kernel.ready();
        // user answers to its program's input
        if (this._inputMode) {
            this._term.set_prompt("");
            this._inputMode = false;
            this.pause();
            this._inputResolve?.(command);
            return;
        }
        // user interacts with REPL
        this._buffer.push(command);
        const source = this._buffer.join("\n");
        if (await this._kernel.more(source)) {
            this._term.set_prompt(this._kernel.ps2());
        }
        else {
            this._term.set_prompt(this._kernel.ps1());
            this.resetBuffer();
            this.launch(source, true);
        }
    }
    /**
     * Force waiting for input to end.
     */
    async _stopWaitInput() {
        if (!this._inputMode)
            return;
        this._inputResolve?.();
        this._inputMode = false;
    }
    /**
     * Print a string in the terminal.
     */
    echo(message) {
        // JQuery.terminal adds a trailing newline that is not easy
        // to remove with the current API. Doing our best here.
        message = message.toString();
        // prompt can be polluted with previous echo
        // _prompt_tail is the line part just before the prompt
        const term = this._term;
        let prompt_tail = this._prompt_tail ?? "";
        let prompt = term.get_prompt();
        if (prompt.startsWith(prompt_tail))
            prompt = prompt.slice(prompt_tail.length);
        else
            prompt_tail = "";
        // here, prompt and _prompt_tail should be correctly isolated
        const lines = message.split("\n");
        lines[0] = prompt_tail + lines[0];
        prompt_tail = lines.pop() ?? "";
        term.set_prompt(prompt_tail + prompt);
        if (lines.length) {
            // term.echo("") does not display blank line
            // so we replace this call with term.echo('\b')
            term.echo(lines.join("\n") || "\b");
        }
        this._prompt_tail = prompt_tail;
    }
    /**
     * Print error in terminal (in red).
     */
    error(message) {
        // JQuery.terminal adds a trailing newline that is not easy
        // to remove with the current API. Doing our best here.
        message = message.toString();
        return this._term.error(message.replace(/\n+$/, ""));
    }
    /**
     * Pause the terminal execution (usefull to wait for event or promise).
     */
    pause() {
        this._term.pause();
    }
    /**
     * Resume the terminal execution (see `pause`).
     */
    wakeup() {
        this._term.resume();
    }
    /**
     * Recover the terminal as it was at start.
     */
    clear() {
        this._term.clear();
        this.echo(this.banner() + "\n");
        this.resetBuffer();
        this._stopWaitInput();
    }
    /**
     * Launch code in terminal.
     */
    launch(code, interactive = true) {
        this._stopWaitInput();
        if (!interactive)
            this.showScript(code);
        this.pause();
        this._term.set_prompt("");
        (async () => {
            await this._kernel.ready();
            this._kernel.dispatchEvent("eval.request", {
                code: code,
                interactive: interactive,
            });
        })();
    }
    /**
     * Give focus to terminal.
     */
    focus() {
        this._term.focus();
    }
    /**
     * Show script in terminal with content as dropdown
     * (should improve readability).
     */
    showScript(code) {
        code = `# script executed\n${code}`;
        let script = `${this._kernel.ps1()}`;
        script += code.split("\n").join(`\n${this._kernel.ps2()}`);
        script += "\n";
        this.echo(script);
        const output = this._elem.querySelector(".terminal-output")?.lastElementChild;
        const header = output?.firstElementChild;
        if (header == null)
            return;
        header.classList.add("exec-script-header");
        for (const e of header.children)
            e.style.backgroundColor = "inherit";
        function hideShow() {
            const converter = {
                none: "block",
                "": "none",
                block: "none",
            };
            if (output == null)
                return;
            for (const e of output.children) {
                if (e === header)
                    continue;
                const style = e.style;
                style.display = converter[style.display];
            }
        }
        header.addEventListener("click", hideShow);
        // remember to remove listeners on destroy
        this._destroyCb.push(() => header.removeEventListener("click", hideShow));
        hideShow();
    }
    /**
     * Destroy all created by terminal.
     */
    destroy() {
        this._destroyCb.forEach((cb) => cb());
        this._destroyCb = [];
        this._term.destroy();
        this._term.empty();
        this._term.off();
    }
}
