import ace, { Ace } from "ace-builds";
import "ace-builds/src-noconflict/ext-language_tools";
// importing ace-builds/esm-resolver.js bundle all languages/themes etc...
// we explicitly load what is needed.
/* languages */
ace.config.setModuleLoader("ace/mode/python", () => import("ace-builds/src-noconflict/mode-python.js"));
ace.config.setModuleLoader("ace/mode/python3", () => import("ace-builds/src-noconflict/mode-python.js"));
ace.config.setModuleLoader("ace/mode/javascript", () => import("ace-builds/src-noconflict/mode-javascript.js"));
ace.config.setModuleUrl("ace/mode/javascript_worker", new URL("ace-builds/src-noconflict/worker-javascript.js", import.meta.url)
    .href);
ace.config.setModuleLoader("ace/mode/ocaml", () => import("ace-builds/src-noconflict/mode-ocaml.js"));
ace.config.setModuleLoader("ace/mode/sql", () => import("ace-builds/src-noconflict/mode-sql.js"));
/* themes */
ace.config.setModuleLoader("ace/theme/monokai", () => import("ace-builds/src-noconflict/theme-monokai.js"));
ace.config.setModuleLoader("ace/theme/xcode", () => import("ace-builds/src-noconflict/theme-xcode.js"));
export { Ace };
export default ace;
