import ace from "./ace";
/**
 * Wrapper class around Ace editor.
 */
export default class Editor {
    constructor(element, kernel, onSetContent, onChange) {
        this._kernel = kernel;
        this._onSetContent = onSetContent;
        this._editor = ace.edit(element);
        this._editor.setOptions({
            enableLiveAutocompletion: true,
            enableBasicAutocompletion: true,
            highlightActiveLine: false,
            highlightSelectedWord: true,
            fontSize: "12pt",
        });
        // connect onchange
        if (onChange != null)
            this._editor.session.on("change", () => onChange());
        /* editor's completion */
        // removing all completers and keeping track of local completer
        const localCompleter = this._editor.completers[1]; // any hint to detect this dynamically?
        this._editor.completers = [
            {
                getCompletions: async (editor, session, pos, prefix, callback) => {
                    // get local completions (from editor, not namespace)
                    let locals = [];
                    localCompleter.getCompletions(editor, session, pos, prefix, function (_, completions) {
                        locals = completions;
                    });
                    // recover editor content up to position
                    let lines = editor.getValue().split("\n");
                    lines = lines.slice(0, pos.row + 1);
                    lines[lines.length - 1] = lines[lines.length - 1].slice(0, pos.column);
                    const src = lines.join("\n");
                    // Basthon completion
                    const kernelCompletions = await this._kernel.complete(src);
                    if (!kernelCompletions?.length)
                        return;
                    const start = kernelCompletions[1];
                    let completions = kernelCompletions[0];
                    // removing prefix
                    const basthon_prefix = src.slice(start, -prefix.length);
                    completions = completions.map((c) => c.slice(basthon_prefix.length));
                    // union with local completions
                    const completionsSet = new Set(completions);
                    for (let c of locals) {
                        c = c.value;
                        if (!(completionsSet.has(c) || completionsSet.has(c + "(")))
                            completionsSet.add(c);
                    }
                    // rendering
                    callback(null, [...completionsSet].map((value) => ({
                        caption: value,
                        value: value,
                        meta: "code",
                        score: 100,
                    })));
                },
            },
        ];
        this._editor.focus();
    }
    /**
     * Set Ace mode from language.
     */
    async setLanguage(language) {
        // some languages are not supported (e.g. xcas)
        if (!["sql", "javascript", "python3", "ocaml"].includes(language))
            return;
        await new Promise((resolve) => {
            this._editor.session.setMode(`ace/mode/${language}`, resolve);
        });
    }
    /**
     * Set Ace theme from our theme.
     */
    async setTheme(theme) {
        const aceTheme = theme === "dark" ? "monokai" : "xcode";
        await new Promise((resolve) => {
            this._editor.setTheme(`ace/theme/${aceTheme}`, resolve);
        });
    }
    /**
     * Dispatch action to set content.
     */
    setContent(content) {
        this._onSetContent?.(content);
    }
    /**
     * Set Ace editor content.
     */
    setContentNoDispatch(content) {
        if (content != null)
            this._editor.setValue(content, -1);
    }
    /**
     * Get editor's content
     */
    getContent() {
        return this._editor.getValue();
    }
    /**
     * Destroy all created by ace.
     */
    destroy() {
        this._editor.destroy();
        // this is advertised by ace but conflicts with react -> disabled
        // aceEditor.container.remove();
    }
}
