/**
 * Fix Matplotlib icons using Fontawesome not loaded globaly.
 */
const fixMatplotlibIcons = async (element) => {
    if (element.getAttribute("id")?.startsWith("matplotlib_")) {
        const fa = await import("@fortawesome/fontawesome-svg-core");
        const fas = await import("@fortawesome/free-solid-svg-icons");
        fa.library.add(fas.faHome, fas.faArrowLeft, fas.faArrowRight, fas.faArrows, fas.faSearchPlus);
        for (const button of element.querySelectorAll(".matplotlib-toolbar-button")) {
            button.classList.remove("fa");
            const faClass = Array.from(button.classList).find((c) => c.startsWith("fa-"));
            if (faClass != null) {
                const icon = fa.parse.icon(faClass);
                const node = fa.icon(icon)?.node?.[0];
                if (node != null)
                    button.appendChild(node);
            }
        }
    }
};
/**
 * Dedicated class to manage action not managed by react.
 */
export default class Graphics {
    constructor(element, kernel, onContentUpdate) {
        // array of destroy callbacks
        this._destroyCb = [];
        this._elem = element;
        this._onContentUpdate = onContentUpdate;
        const callback = this.display.bind(this);
        kernel.addEventListener("eval.display", callback);
        // remember to remove listeners on destroy
        this._destroyCb.push(() => kernel.removeEventListener("eval.display", callback));
    }
    /**
     * Set the dynamic IFrame handler called on each new dynamic iframe.
     */
    setDynamicIFrameHandler(handler) {
        this._handleDynamicIFrame = handler;
    }
    /**
     * Same as that.innerHTML = html but with script execution support.
     */
    setInnerHTML(html, runScripts = false) {
        // FIXME: sanitize input html
        if (this._elem == null)
            return;
        this._elem.innerHTML = html;
        if (!runScripts)
            return;
        for (const oldScript of this._elem.querySelectorAll("script")) {
            const newScript = document.createElement("script");
            for (const attr of oldScript.attributes)
                newScript.setAttribute(attr.name, attr.value);
            newScript.appendChild(document.createTextNode(oldScript.innerHTML));
            oldScript.parentNode?.replaceChild(newScript, oldScript);
        }
    }
    /**
     * CSS transform the first child element to fit the view.
     */
    fitContent() {
        for (const child of this._elem.children) {
            if (!(child instanceof HTMLElement))
                continue;
            if (["DIV", "IFRAME"].includes(child.tagName)) {
                const ratio = Math.min((this._elem.offsetWidth - 5) / child.scrollWidth, (this._elem.offsetHeight - 5) / child.scrollHeight, 1);
                child.style.transform = `scale(${ratio})`;
            }
            // p5 specific case
            if (child.tagName === "DIV") {
                const child2 = child.firstElementChild;
                if (child2.tagName === "CANVAS" &&
                    child2.classList.contains("p5Canvas")) {
                    child.style.position = "relative";
                    child.style.width = "99%";
                    child.style.height = "99%";
                    child.style.transform = "unset";
                    child2.style.position = "absolute";
                    child2.style.top = "50%";
                    child2.style.left = "50%";
                    child2.style.transform = "translate(-50%, -50%)";
                    child2.style.maxWidth = "100%";
                    child2.style.maxHeight = "100%";
                    child2.style.width = "unset";
                    child2.style.height = "unset";
                }
                else if (child2.tagName === "VIDEO") {
                    child.style.height = "100%";
                    child2.style.width = "100%";
                    child2.style.height = "100%";
                }
            }
        }
    }
    /**
     * To be called when resized.
     */
    onResize() {
        this.fitContent();
    }
    /**
     * Display an element from Basthon data.
     */
    async display(data) {
        this.clean();
        switch (data.display_type) {
            case "dom-node":
                const elem = data.content;
                await fixMatplotlibIcons(elem);
                this._elem?.appendChild(elem);
                break;
            case "multiple":
                /* typically dispached by display() */
                for (let mime of [
                    "image/svg+xml",
                    "image/png",
                    "text/latex",
                    "text/html",
                    "text/dynamic-iframe",
                    "text/plain",
                ]) {
                    if (mime in data.content) {
                        let content = data.content[mime];
                        switch (mime) {
                            case "image/png":
                                content = `<img src="data:image/png;base64,${content}">`;
                                break;
                            case "text/dynamic-iframe":
                                const dataURL = `data:text/html;charset=utf-8,${encodeURIComponent(content)}`;
                                content = `<iframe allowFullscreen class="basthon-dynamic-iframe" frameborder="0" src="${dataURL}"></iframe>`;
                                break;
                            case "text/latex":
                                if (window.MathJax != null)
                                    break;
                                // dynamically loading MathJax
                                console.log("Loading MathJax (LaTeX expression needs it).");
                                await new Promise((resolve, reject) => {
                                    const script = document.createElement("script");
                                    script.type = "text/javascript";
                                    script.onload = resolve;
                                    script.onerror = reject;
                                    script.src =
                                        "https://cdn.jsdelivr.net/npm/mathjax@3.0.5/es5/tex-mml-chtml.js";
                                    document.getElementsByTagName("head")[0].appendChild(script);
                                });
                                break;
                            default:
                                break;
                        }
                        this.setInnerHTML(content, true);
                        if (mime === "text/latex")
                            window.MathJax?.typeset?.();
                        if (mime === "text/dynamic-iframe") {
                            const elem = this._elem.firstElementChild;
                            const o = new ResizeObserver(() => this.fitContent());
                            o.observe(elem);
                            this._handleDynamicIFrame?.(elem);
                        }
                        break;
                    }
                }
                break;
            default:
                console.error(`Not supported node type '${data.display_type}' in eval.display result processing.`);
        }
        // update size
        this.fitContent();
        this._onContentUpdate();
    }
    /**
     * Clean graphics.
     */
    clean() {
        this._elem.textContent = "";
    }
    /**
     * Destroy all created by graphics.
     */
    destroy() {
        this._destroyCb.forEach((cb) => cb());
        this._destroyCb = [];
        this.clean();
    }
}
